import { mkdir, open, rm, stat, writeFile } from "node:fs/promises";
import path from "node:path";
import type { StorageDriver } from "./driver";
import { signToken } from "./token";

/** Keys are generated by the server (`incoming/<cuid>`); anything else is rejected. */
export function safeLocalPath(root: string, key: string): string {
  if (!/^[a-z]+\/[a-z0-9]+$/.test(key)) throw new Error("Invalid storage key");
  return path.join(path.resolve(root), ...key.split("/"));
}

export function localDriver(root: string, secret: string): StorageDriver {
  return {
    name: "local",
    async uploadTarget(key, contentType, size, ttlSeconds) {
      const token = signToken(
        { op: "put", key, exp: Date.now() + ttlSeconds * 1000, size, type: contentType },
        secret,
      );
      return {
        url: `/api/files/local?token=${encodeURIComponent(token)}`,
        method: "PUT",
        headers: { "content-type": contentType },
      };
    },
    async size(key) {
      try {
        return (await stat(safeLocalPath(root, key))).size;
      } catch {
        return null;
      }
    },
    async readStart(key, length) {
      const handle = await open(safeLocalPath(root, key), "r");
      try {
        const buffer = new Uint8Array(length);
        const { bytesRead } = await handle.read(buffer, 0, length, 0);
        return buffer.slice(0, bytesRead);
      } finally {
        await handle.close();
      }
    },
    async downloadUrl(key, fileName, contentType, ttlSeconds) {
      const token = signToken(
        { op: "get", key, exp: Date.now() + ttlSeconds * 1000, type: contentType, name: fileName },
        secret,
      );
      return `/api/files/local?token=${encodeURIComponent(token)}`;
    },
    async delete(key) {
      await rm(safeLocalPath(root, key), { force: true });
    },
  };
}

/** Writes an upload for the local route handler (exclusive create: never overwrites). */
export async function writeLocal(root: string, key: string, bytes: Uint8Array) {
  const file = safeLocalPath(root, key);
  await mkdir(path.dirname(file), { recursive: true });
  await writeFile(file, bytes, { flag: "wx" });
}
